from toolbank import RETRY_PROFILES, SystemError_, attempt, ctl_click, ctl_text, hotkey, screen_capture


def save_record(window, ref, run_folder):
    """Desktop app: click Save, confirm the status bar shows the reference; Ctrl+S as the fallback."""
    def saved():
        return ref in (ctl_text(window, auto_id="statusBar", timeout=1) or "")

    def recover():
        hotkey("esc")                                     # close whatever pop-up took focus
        window.set_focus()

    return attempt(
        lambda: ctl_click(window, title="Save", control_type="Button"),
        verify=saved,
        recover=recover,
        fallbacks=[lambda: hotkey("ctrl", "s")],
        already_done=saved,                               # never save twice
        on_give_up=lambda: screen_capture(run_folder / f"save_failed_{ref}.png"),
        name=f"save {ref}",
        **RETRY_PROFILES["ui"],
    )


def search_account(b, account):
    """Web portal (b = toolbank Browser): search, confirm the account appears; Enter as the fallback."""
    return attempt(
        lambda: (b.fill("#account", account), b.click("button#search")),
        verify=lambda: b.exists(f"text={account}", ms=500),
        recover=lambda: b.press("#account", "Escape"),
        fallbacks=[lambda: b.press("#account", "Enter")],
        on_give_up=lambda: b.screenshot(f"search_failed_{account}"),
        name=f"search {account}",
        **RETRY_PROFILES["ui"],
    )


class FakeTime:
    """For the demo and tests: sleeping only moves this clock, so waits take no real time."""
    now = 0.0

    def clock(self):
        return self.now

    def sleep(self, s):
        self.now += s


def demo(tmp):
    """A fake screen that shows a pop-up on the first click: the step recovers and succeeds on try 2.
    A screen that never responds: the step gives up with evidence and STEP_FAILED."""
    t = FakeTime()
    screen = {"popup": True, "saved": False, "clicks": 0}

    def click_save():
        screen["clicks"] += 1
        if screen["popup"]:
            return                                        # the click lands on the pop-up, nothing is saved
        screen["saved"] = True

    def close_popup():
        screen["popup"] = False

    log = []
    attempt(click_save, verify=lambda: screen["saved"], recover=close_popup, already_done=lambda: screen["saved"],
            name="save T1", log=log.append, sleep=t.sleep, clock=t.clock, **RETRY_PROFILES["ui"])
    assert screen == {"popup": False, "saved": True, "clicks": 2}
    assert log[-1] == "save T1: ok on primary try 2"

    evidence = []
    try:
        attempt(lambda: None, verify=lambda: False, fallbacks=[lambda: None],
                on_give_up=lambda: evidence.append(tmp / "save_failed_T2.png"),
                name="save T2", log=log.append, sleep=t.sleep, clock=t.clock, **RETRY_PROFILES["ui"])
    except SystemError_ as e:
        assert e.code == "STEP_FAILED" and len(e.context["history"]) == 4 and evidence
    else:
        raise AssertionError("expected STEP_FAILED")

import pandas as pd

from toolbank import (BusinessError, Checkpoint, SystemError_, cents, get_logger, process_all, progress,
                      safe_write_excel, synth)

ACTIONS = {"MISSING_ACCOUNT": "Add the account number in the source file",      # signed off by the process owner
           "BAD_AMOUNT": "Correct the amount in the source file",
           "NOT_IN_LEDGER": "Check whether the payment was booked",
           "AMOUNT_MISMATCH": "Check the booking with the ledger team"}


def blank(value):
    """True for None, NaN and text that is only spaces."""
    return value is None or (not isinstance(value, str) and pd.isna(value)) or not str(value).strip()


def ref_key(item):
    """Checkpoint key: the reference trimmed and in capitals; '' for a blank one (process_all: MISSING_KEY)."""
    return "" if blank(item.get("ref")) else str(item["ref"]).strip().upper()


def check_payment(item, ledger):
    """Business rules for one payment against ledger(ref) -> amount or None; bad data raises BusinessError."""
    ref = item["ref"]
    if blank(item.get("account")):
        raise BusinessError("account is blank", code="MISSING_ACCOUNT", ref=ref)
    try:
        amount = cents(item.get("amount"))
    except (TypeError, ValueError, OverflowError):        # blank, NaN, inf or text; the error would show the value
        raise BusinessError("amount is blank or not a number", code="BAD_AMOUNT", ref=ref) from None
    booked = ledger(ref)                                  # OSError / SystemError_ here: left for the re-run
    if booked is None:
        raise BusinessError("reference not found in the ledger", code="NOT_IN_LEDGER", ref=ref)
    if cents(booked) != amount:
        raise BusinessError("amount differs from the ledger", code="AMOUNT_MISMATCH", ref=ref)


def exit_code(failures):
    """3 if any failure is retryable (re-run resumes), 2 for business exceptions only, 0 when there are none."""
    return 3 if failures["retryable"].any() else 2 if len(failures) else 0


def write_exceptions(failures, path):
    """Exceptions report for the owner: reference, code, reason and the next action."""
    action = [("Re-run picks it up; tell support if it stays" if retry else ACTIONS.get(code, "Check the source data"))
              for code, retry in zip(failures["code"], failures["retryable"])]
    report = failures[["item", "code", "message", "retryable"]].assign(action=action)
    return safe_write_excel(path, {"Exceptions": report}, overwrite=True)


def run_items(items, handle, run_folder, log, every=100):
    """Work each open item once (items: a list of dicts with a 'ref'), resuming from the checkpoint; returns the
    exit code. Stops with SystemError_ SYSTEM_STREAK (exit 3) or the bug that stopped it (exit 5)."""
    report = run_folder / "exceptions.xlsx"
    report.unlink(missing_ok=True)                        # a report on file always belongs to a finished run
    cp = Checkpoint(run_folder / "checkpoint.json")
    queue = progress(items, every=every, label="items", log=log.info)
    _, failures = process_all(queue, handle, max_consecutive_system=3, checkpoint=cp,
                              key=ref_key, log=log.warning)
    write_exceptions(failures, report)
    log.info("items finished", extra={"event": "items", "rows": len(items), "done": len(cp.done),
                                      "count": len(failures)})
    return exit_code(failures)


def demo(tmp):
    """8 payments: a blank account, a text amount, an amount 1 cent off the ledger, one ledger time-out, and
    PAY-1002 sent twice (' pay-1002'). Run 1 exits 3; the re-run, on the file re-sorted, handles only the open items
    and exits 2; after the owner's fix it exits 0. A ledger that is down stops the loop after 3 items."""
    df = synth(8, {"n": ("seq", 1001), "account": ("pattern", "999-99999-9"), "amount": ("number", 10, 5000)})
    items = [{"ref": f"PAY-{r.n}", "account": r.account, "amount": r.amount} for r in df.itertuples()]
    book = {item["ref"]: item["amount"] for item in items}
    items[2]["account"] = " "                             # PAY-1003: blank account
    items[3]["amount"] = "1,234 USD"                      # PAY-1004: text where a number belongs
    book["PAY-1005"] += 0.01                              # PAY-1005: one cent off
    items.append({**items[1], "ref": " pay-1002"})        # PAY-1002 again, other case and spaces
    timeouts, outage, handled = {"PAY-1007"}, [], []

    def ledger(ref):
        if outage:
            raise SystemError_("ledger not answering", code="LEDGER_DOWN", ref=ref)
        if ref in timeouts:
            timeouts.discard(ref)
            raise OSError("ledger did not answer within 30 s")
        return book.get(ref)

    def handle(item):
        handled.append(item["ref"])
        check_payment(item, ledger)

    def run(batch, folder=tmp):
        handled.clear()
        return run_items(batch, handle, folder, log, every=4)

    log = get_logger(tmp / "run.log.jsonl", name="item_loop", console=False)
    report = lambda: pd.read_excel(tmp / "exceptions.xlsx")
    assert run(items) == 3 and len(handled) == 8          # the second PAY-1002 is reported, not worked
    assert dict(zip(report()["item"], report()["code"])) == {
        "PAY-1003": "MISSING_ACCOUNT", "PAY-1004": "BAD_AMOUNT", "PAY-1005": "AMOUNT_MISMATCH", "PAY-1007": "SYSTEM",
        "PAY-1002": "DUPLICATE_KEY"}
    assert run(items[::-1]) == 2 and handled == ["PAY-1007", "PAY-1005", "PAY-1004", "PAY-1003"]   # open items only
    items.pop()                                           # the owner removes the repeat and fixes the data
    items[2]["account"], items[3]["amount"], book["PAY-1005"] = "123-45678-9", book["PAY-1004"], items[4]["amount"]
    assert run(items) == 0 and handled == ["PAY-1003", "PAY-1004", "PAY-1005"] and report().empty

    outage.append(True)
    try:
        run(items, tmp / "outage")
    except SystemError_ as e:
        assert e.code == "SYSTEM_STREAK" and len(handled) == 3
        assert not (tmp / "outage" / "checkpoint.json").exists() and not (tmp / "outage" / "exceptions.xlsx").exists()
    else:
        raise AssertionError("expected SYSTEM_STREAK")
    text = (tmp / "run.log.jsonl").read_text(encoding="utf-8")
    assert "skip PAY-1003: [MISSING_ACCOUNT]" in text and "items 9/9 (100%)" in text and "system failure 3/3" in text
    assert "1,234" not in text and str(items[4]["amount"]) not in text    # ids and codes in the log, never amounts

from datetime import date, datetime, timedelta, timezone
from pathlib import Path
from zoneinfo import ZoneInfo

from toolbank import (BusinessError, RobotError, add_business_days, adjust_business_day, assert_before_cutoff,
                      file_sha256, is_business_day, load_holidays, month_end, process_all, today_in)

TEAM_TZ, TEAM_MARKET = "Asia/Singapore", "SG"             # where the operations team works
SPOT_DAYS, MARGIN_MIN = 2, 15                             # T+2 value dates; stop submitting 15 min early


def market_holidays(folder, markets, today, horizon_days=14):
    """Holidays of all the markets in one set; a missing, unreadable or out-of-date file stops the run."""
    years, hols = {today.year, (today + timedelta(days=horizon_days)).year}, set()
    for m in markets:
        try:
            days = load_holidays(Path(folder) / f"holidays_{m}.csv")
        except (OSError, ValueError, KeyError) as e:
            raise RobotError(f"holiday file for {m} unreadable: {e}", code="HOLIDAYS", market=m) from e
        if not years <= {d.year for d in days}:
            raise RobotError(f"holiday file for {m} has no dates for {sorted(years)}", code="HOLIDAYS", market=m)
        hols |= days
    return hols


def plan_run(folder, settle_markets, today=None):
    """The dates for this run, or None on a weekend or team holiday (log 'nothing to do', exit 0)."""
    if isinstance(today, str):
        today = date.fromisoformat(today)                 # a re-run: --business-date 2026-11-25
    today = today or today_in(TEAM_TZ)                    # the team's date, not the server's
    team = market_holidays(folder, [TEAM_MARKET], today)
    if not is_business_day(today, team):
        return None
    settle = team | market_holidays(folder, settle_markets, today)
    files = [Path(folder) / f"holidays_{m}.csv" for m in dict.fromkeys([TEAM_MARKET, *settle_markets])]
    return {"business_date": today, "holidays": settle,
            "value_date": add_business_days(today, SPOT_DAYS, settle),
            "month_end": month_end(today, business=True, holidays=team),
            "holiday_files": {p.name: file_sha256(p) for p in files}}


def roll(scheduled, holidays):
    """A scheduled date on a weekend or holiday -> modified following (never into the next month)."""
    return adjust_business_day(scheduled, holidays, "modified_following")


def before_cutoff(business_date, cutoff="17:30", tz=TEAM_TZ, margin_min=MARGIN_MIN, now=None):
    """Call right before each submit: minutes left, or BusinessError PAST_CUTOFF (hand over, never submit late)."""
    now = (now or datetime.now(ZoneInfo(tz))).astimezone(ZoneInfo(tz))
    if now.date() != business_date:                       # past midnight, or a re-run on a later day
        raise BusinessError(f"it is {now:%Y-%m-%d %H:%M} {tz}, not business date {business_date}: hand over to a "
                            "person", code="PAST_CUTOFF")
    try:
        return assert_before_cutoff(cutoff, tz, now=now, grace_minutes=-margin_min)
    except RobotError as e:
        raise BusinessError(f"now {now:%H:%M}, past the {cutoff} {tz} cut-off less {margin_min} min: hand over to "
                            "a person", code="PAST_CUTOFF") from e


def demo(tmp):
    """2026 calendar: Christmas is skipped, T+2 steps over US Thanksgiving, a Sunday 31st stays in May, submits
    at 17:20 Singapore time or on a later day are handed over, and a stale, unreadable or missing holiday file
    stops the run."""
    (tmp / "holidays_SG.csv").write_text("date\n2026-01-01\n2026-12-25\n2027-01-01\n")
    (tmp / "holidays_US.csv").write_text("date\n2026-01-01\n2026-11-26\n2026-12-25\n2027-01-01\n")
    assert plan_run(tmp, ["US"], today=date(2026, 12, 25)) is None             # holiday: exit 0, nothing to do
    p = plan_run(tmp, ["US"], today="2026-11-25")                             # Wednesday
    assert p["value_date"] == date(2026, 11, 30)                              # Thu 26 is a US holiday: Fri, Mon
    assert add_business_days(p["business_date"], 2, {date(2026, 1, 1)}) == date(2026, 11, 27)   # SG alone: Fri
    assert p["month_end"] == date(2026, 11, 30)
    assert roll(date(2026, 5, 31), p["holidays"]) == date(2026, 5, 29)        # not Monday 1 June
    assert sorted(p["holiday_files"]) == ["holidays_SG.csv", "holidays_US.csv"]
    assert p["holiday_files"]["holidays_US.csv"] == file_sha256(tmp / "holidays_US.csv")

    day = p["business_date"]
    assert before_cutoff(day, now=datetime(2026, 11, 25, 10, 0, tzinfo=ZoneInfo(TEAM_TZ))) == 435  # to 17:15
    late, sent = datetime(2026, 11, 25, 9, 20, tzinfo=timezone.utc), []      # 17:20 in Singapore

    def submit(ref):
        before_cutoff(day, now=late)
        sent.append(ref)
    _, failures = process_all(["PAY-1", "PAY-2"], submit)
    assert sent == [] and failures["code"].tolist() == ["PAST_CUTOFF"] * 2 and not failures["retryable"].any()
    next_morning = datetime(2026, 11, 26, 9, 0, tzinfo=ZoneInfo(TEAM_TZ))   # a re-run for the 25th, at 09:00
    try:
        before_cutoff(day, now=next_morning)
    except BusinessError as e:
        assert e.code == "PAST_CUTOFF"
    else:
        raise AssertionError("a re-run on a later day must not submit")

    (tmp / "holidays_US.csv").write_text("date\n2025-01-01\n2025-12-25\n")     # not updated for 2026
    (tmp / "holidays_GB.csv").write_text("date\nBoxing Day\n")                 # unreadable; HK has no file
    for market in ("US", "GB", "HK"):
        try:
            market_holidays(tmp, [market], date(2026, 11, 25))
        except RobotError as e:
            assert e.code == "HOLIDAYS" and not e.retryable
        else:
            raise AssertionError(f"expected HOLIDAYS for {market}")
